[("سلاد کے لیے","200 گرام رومین لیٹوس، کٹا ہوا"),("سلاد کے لیے","2 درمیانے کھیرے، کٹے ہوئے (250 گرام)"),("سلاد کے لیے","2 ٹماٹر، کٹے ہوئے (250 گرام)"),("سلاد کے لیے","1 ہری شملہ مرچ (100 گرام) اور 1 سرخ شملہ مرچ (100 گرام)، کٹی ہوئی"),("سلاد کے لیے","4 مولیاں، گول کٹی ہوئی (60 گرام) اور 3 ہرے پیاز (40 گرام)"),("سلاد کے لیے","30 گرام اجمود اور 10 گرام تازہ پودینہ، کٹا ہوا"),("سلاد کے لیے","1 چھوٹا سالم گندم کا پیٹا (60 گرام)، چوکور ٹکڑوں میں کٹا ہوا"),("ڈریسنگ کے لیے","1½ کھانے کے چمچ زیتون کا تیل (20 گرام)"),("ڈریسنگ کے لیے","2 کھانے کے چمچ لیموں کا رس (30 گرام) اور 1 کھانے کا چمچ سرکہ (15 گرام)"),("ڈریسنگ کے لیے","1 چائے کا چمچ سماق، ¼ چائے کا چمچ زیرہ، 1 چھوٹا لہسن کا جوا، کچلا ہوا (3 گرام)"),("ڈریسنگ کے لیے","⅓ چائے کا چمچ نمک (2 گرام)")],
["روٹی کے چوکور ٹکڑے ٹرے پر پھیلائیں اور 200 °C کے اوون میں 8–10 منٹ ٹوسٹ کریں یہاں تک کہ کرکرے ہو جائیں۔","لیٹوس، کھیرا، ٹماٹر، شملہ مرچیں، مولیاں، ہرے پیاز، اجمود اور پودینہ ایک بڑے پیالے میں ڈالیں۔","زیتون کے تیل کو لیموں کے رس، سرکے، سماق، زیرے، لہسن اور نمک کے ساتھ پھینٹیں یہاں تک کہ ذرا گاڑھا ہو جائے۔","ڈریسنگ سبزیوں پر ڈال کر ملائیں، پھر پیش کرنے سے ذرا پہلے ٹوسٹ کی ہوئی روٹی شامل کریں اور اوپر تھوڑا سا سماق چھڑکیں۔"],
